// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2, PuttyV2 as PuttyC} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;

    function setUp() public { c = new PuttyV2("", 0, address(this)); }

    // fuzz parameters: makerKey (private key for order.maker), isCall, isLong, baseAsset (address), strike, premium, duration, expiration, nonce
    // We fuzz a few key order fields so fuzzer can find case where isLong == true (the mutant differs then).
    function testFuzz_property(uint256 makerKey, bool isCall, bool isLong, address baseAsset, uint256 strike, uint256 premium, uint256 duration, uint256 expiration, uint256 nonce) public {
        makerKey = bound(makerKey, 1, 115792089237316195423570985008687907852837564279074904382605163141518161494336);
        // keep domain wide but sensible
        vm.assume(duration < 10_000 days);
        // ensure expiration in future
        vm.warp(1);
        vm.assume(expiration > block.timestamp);
        // need baseAsset to be contract (the reference requires baseAsset.code.length > 0)
        // deploy a simple ERC20-like dummy contract to serve as baseAsset
        DummyERC20 token = new DummyERC20();
        baseAsset = address(token);

        // choose maker address from makerKey
        address maker = vm.addr(uint256(makerKey));

        // construct minimal order with empty arrays
        PuttyV2.Order memory order = PuttyV2.Order({
            maker: maker,
            isCall: isCall,
            isLong: isLong,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: new address[](0),
            floorTokens: new address[](0),
            erc20Assets: new PuttyV2.ERC20Asset[](0),
            erc721Assets: new PuttyV2.ERC721Asset[](0)
        });

        // compute orderHash as contract would
        bytes32 orderHash = c.hashOrder(order);

        // sign the hash using EIP-712 domain separator -- c expects a signature over the orderHash (already domain hashed)
        // The contract's SignatureChecker expects the signature to be over the bytes32 passed (hashOrder return), and uses ECDSA.recover
        // Use vm.sign with makerKey; v,r,s over keccak256("\x19Ethereum Signed Message:\n32" + orderHash) is NOT used here: SignatureChecker calls ECDSA.tryRecover(hash, signature) directly,
        // so the signer must sign the raw orderHash via eth_sign-like semantics (vm.sign gives v,r,s for the 32-byte hash passed directly).
        (uint8 v, bytes32 r, bytes32 s) = vm.sign(uint256(makerKey), orderHash);
        bytes memory signature = abi.encodePacked(r, s, v);

        // fund maker if needed and approve transfers: token is DummyERC20 with unlimited behavior for safeTransferFrom in tests
        vm.deal(maker, 1 ether);

        // Now call fillOrder as the counterparty (msg.sender). We fuzz caller as address(this)
        // Use try/catch to ensure test doesn't revert unexpectedly; we assert the invariant below using getters.
        bool ok;
        try c.fillOrder{value: 0}(order, signature, new uint256[](0)) returns (uint256 positionId) {
            ok = true;
            // read what the contract set
            uint256 posExpAtOrderKey = c.positionExpirations(uint256(orderHash));
            uint256 oppositeId = uint256(c.hashOppositeOrder(order));
            uint256 posExpAtOpposite = c.positionExpirations(oppositeId);

            // GENERAL RULE (reference): if order.isLong == true, positionExpirations[uint256(orderHash)] == block.timestamp + duration,
            // else (order.isLong == false) positionExpirations[oppositeId] == block.timestamp + duration.
            // We assert that property holds in the reference; the mutant that always writes to positionId (oppositeId)
            // will break when isLong == true (it writes to oppositeId instead of orderHash).
            if (isLong) {
                assertTrue(posExpAtOrderKey == block.timestamp + duration);
            } else {
                assertTrue(posExpAtOpposite == block.timestamp + duration);
            }
        } catch {
            // If fillOrder reverts, we still consider that a failure to set state; call should not revert for valid inputs in reference
            ok = false;
            // To keep a single assertion as required, assert that calling failed is impossible for well-formed inputs in reference
            // However, to avoid false positives from absurd inputs, we only assert false when order expiration in future and baseAsset is contract (ensured)
            assertTrue(false);
        }

        // ensure at least one successful path executed (this is not strictly necessary but keeps fuzz meaningful)
        assertTrue(ok);
    }
}

// Minimal dummy ERC20 that accepts any safeTransferFrom / transfer calls in tests
contract DummyERC20 {
    function transfer(address, uint256) external pure returns (bool) { return true; }
    function transferFrom(address, address, uint256) external pure returns (bool) { return true; }
    function approve(address, uint256) external pure returns (bool) { return true; }
    // allow .code.length > 0 since this is a contract
}
